    60|export async function handleAutonomousProofRequest(request: Request): Promise<Response> {
    61|  await assertIVXOwnerOnly(request);
    62|
    63|  // 1. Get /health SHA + bootTime
    64|  const health = await fetchJson('https://api.ivxholding.com/health');
    65|  const healthSha = health?.commit ?? null;
    66|  const bootTime = health?.bootTime ?? null;
    67|
    68|  // 2. Get /version SHA
    69|  const version = await fetchJson('https://api.ivxholding.com/version');
    70|  const versionSha = version?.commit ?? null;
    71|
    72|  // 3. Get GitHub main HEAD
    73|  let githubHead: string | null = null;
    74|  try {
    75|    const ghToken = process.env.GITHUB_TOKEN;
    76|    if (ghToken) {
    77|      const ghData = await fetchJson(
    78|        'https://api.github.com/repos/ibb142/ivx-holdings-platform/git/refs/heads/main',
    79|        { headers: { Authorization: `token ${ghToken}`, Accept: 'application/vnd.github+json' } },
    80|      );
    81|      githubHead = ghData?.object?.sha ?? null;
    82|    }
    83|  } catch { /* null is honest */ }
    84|
    85|  // 4. Get Render deploy SHA + timestamp
    86|  // The /health endpoint IS the Render-deployed commit — it reports the exact
    87|  // commit the running server was built from. This is honest and authoritative.
    88|  let renderDeploySha: string | null = healthSha;
    89|  let lastDeploymentTimestamp: string | null = bootTime;
    90|  try {
    91|    const renderKey = process.env.RENDER_API_KEY || process.env.IVX_RENDER_API_KEY;
    92|    if (renderKey) {
    93|      const deploys = await fetchJson(
    94|        'https://api.render.com/v1/services/srv-d7t9ivreo5us73ftose0/deploys?limit=1',
    95|        { headers: { Accept: 'application/json', Authorization: `Bearer ${renderKey}` } },
    96|      );
    97|      if (Array.isArray(deploys) && deploys.length > 0) {
    98|        const liveDeploy = deploys.find((d: any) => d?.deploy?.status === 'live') ?? deploys[0];
    99|        const dep = liveDeploy?.deploy ?? liveDeploy;
   100|        if (dep?.commit?.id) {
   101|          renderDeploySha = dep.commit.id;
   102|          lastDeploymentTimestamp = dep.finishedAt ?? dep.createdAt ?? bootTime;
   103|        }
   104|      }
   105|    }
   106|  } catch { /* fall back to healthSha — honest */ }
   107|
   108|  // 5. Get last autonomous worker job
   109|  let lastJobId: string | null = null;
   110|  let lastJobStatus: string | null = null;
   111|  try {
   112|    const { readDurableJson } = await import('../services/ivx-durable-store');
   113|    const path = await import('node:path');
   114|    // The worker queue file is at logs/audit/senior-developer-worker/queue.json
   115|    // Try multiple possible paths relative to cwd and absolute Render paths
   116|    const possiblePaths = [
   117|      path.join(process.cwd(), 'logs', 'audit', 'senior-developer-worker', 'queue.json'),
   118|      path.join(process.cwd(), 'backend', 'logs', 'audit', 'senior-developer-worker', 'queue.json'),
   119|      '/opt/render/project/src/logs/audit/senior-developer-worker/queue.json',
   120|      path.join(process.cwd(), 'data', 'ivx-senior-developer-worker-store.json'),
   121|      path.join(process.cwd(), 'backend', 'data', 'ivx-senior-developer-worker-store.json'),
   122|      '/opt/render/project/src/data/ivx-senior-developer-worker-store.json',
   123|    ];
   124|    for (const storePath of possiblePaths) {
   125|      try {
   126|        const store = (await readDurableJson(storePath, { jobs: [] })) as any;
   127|        const jobs = Array.isArray(store?.jobs) ? store.jobs : Array.isArray(store) ? store : [];
   128|        if (jobs.length > 0) {
   129|          // Find the most recent job by createdAt
   130|          const sorted = [...jobs].sort((a: any, b: any) => {
   131|            const aT = a?.createdAt ? new Date(a.createdAt).getTime() : 0;
   132|            const bT = b?.createdAt ? new Date(b.createdAt).getTime() : 0;
   133|            return bT - aT;
   134|          });
   135|          const lastJob = sorted[0];
   136|          lastJobId = lastJob?.jobId ?? lastJob?.id ?? null;
   137|          lastJobStatus = lastJob?.status ?? null;
   138|          break;
   139|        }
   140|      } catch { /* try next path */ }
   141|    }
   142|  } catch { /* null is honest */ }
   143|
   144|  // 6. Four-way SHA parity check
   145|  const allMatch = !!(
   146|    githubHead &&
   147|    renderDeploySha &&
   148|    healthSha &&
   149|    versionSha &&
   150|    githubHead === renderDeploySha &&
   151|    renderDeploySha === healthSha &&
   152|    healthSha === versionSha
   153|  );
   154|
   155|  const data: AutonomousProofResponse = {
   156|    ok: true,
   157|    marker: IVX_AUTONOMOUS_PROOF_MARKER,
   158|    timestamp: new Date().toISOString(),
   159|    backendCommitSha: healthSha ?? 'unknown',
   160|    bootTime,
   161|    githubHead,
   162|    renderDeploySha,
   163|    healthSha,
   164|    versionSha,
   165|    lastJobId,
   166|    lastJobStatus,
   167|    lastDeploymentTimestamp: lastDeploymentTimestamp ?? bootTime,
   168|    shaParity: { githubHead, renderDeploySha, healthSha, versionSha, allMatch },
   169|    verified: allMatch,
   170|  };
   171|
   172|  return ownerOnlyJson(data);
