  1136|  if (!members || members.length === 0) return [];
  1137|
  1138|  // Group members by cohort date
  1139|  const cohorts: Map<string, typeof members> = new Map();
  1140|  for (const m of members) {
  1141|    const cohortDate = truncateDate(m.first_seen, periodType);
  1142|    if (!cohorts.has(cohortDate)) cohorts.set(cohortDate, []);
  1143|    cohorts.get(cohortDate)!.push(m);
  1144|  }
  1145|
  1146|  const results: RetentionCohort[] = [];
  1147|  const now = new Date();
