  1152|    const cohortStartDate = new Date(cohortDate);
  1153|
  1154|    // Calculate retention for periods 0-12
  1155|    const maxPeriods = 12;
  1156|    for (let p = 0; p <= maxPeriods; p++) {
  1157|      const periodEnd = addPeriod(cohortStartDate, p, periodType);
  1158|      if (periodEnd > now) break;
  1159|
  1160|      // Count members who were still active at this period
  1161|      let retained = 0;
  1162|      for (const m of cohortMembers) {
  1163|        const lastSeen = new Date(m.last_seen);
  1164|        if (lastSeen >= periodEnd) {
  1165|          retained++;
  1166|        }
  1167|      }
