  1169|        period: p,
  1170|        retained_count: retained,
  1171|        retention_pct: cohortSize > 0 ? Math.round((retained / cohortSize) * 100 * 100) / 100 : 0,
  1172|      });
  1173|    }
  1174|
  1175|    // Calculate conversions
