  1188|      day1_retention: day1Retention,
  1189|      cohort_health: avgRetention > 40 ? 'healthy' : avgRetention > 20 ? 'at_risk' : 'critical',
  1190|      conversion_rate: conversionRate,
  1191|      insight: generateCohortInsight(avgRetention, day1Retention, conversionRate, cohortSize),
