  1196|      cohort_size: cohortSize,
  1197|      period_type: periodType,
  1198|      retention_data: retentionData,
  1199|      converted_count: converted,
  1200|      conversion_rate: conversionRate,
  1201|      brain_insights,
  1202|    };
  1203|
  1204|    results.push(cohort);
  1205|
  1206|    // Upsert to database
