  1221|function truncateDate(dateStr: string, periodType: string): string {
  1222|  const d = new Date(dateStr);
  1223|  if (periodType === 'daily') {
  1224|    return d.toISOString().split('T')[0];
  1225|  } else if (periodType === 'weekly') {
  1226|    const day = d.getDay();
  1227|    const diff = d.getDate() - day;
  1228|    return new Date(d.setDate(diff)).toISOString().split('T')[0];
  1229|  } else {
  1230|    return new Date(d.getFullYear(), d.getMonth(), 1).toISOString().split('T')[0];
  1231|  }
