  1233|
  1234|function addPeriod(date: Date, periods: number, periodType: string): Date {
  1235|  const d = new Date(date);
  1236|  if (periodType === 'daily') {
  1237|    d.setDate(d.getDate() + periods);
  1238|  } else if (periodType === 'weekly') {
  1239|    d.setDate(d.getDate() + periods * 7);
  1240|  } else {
  1241|    d.setMonth(d.getMonth() + periods);
  1242|  }
  1243|  return d;
