  1248|  parts.push(`Cohort of ${size} members.`);
  1249|  if (day1Retention < 30) {
  1250|    parts.push(`Day 1 retention is ${day1Retention}% — critical drop-off after first session. Improve onboarding.`);
  1251|  } else if (day1Retention < 50) {
  1252|    parts.push(`Day 1 retention is ${day1Retention}% — below benchmark. Consider push notifications for re-engagement.`);
  1253|  } else {
  1254|    parts.push(`Day 1 retention is ${day1Retention}% — healthy. Members find value quickly.`);
  1255|  }
  1256|  if (avgRetention < 20) {
  1257|    parts.push(`Average retention ${Math.round(avgRetention)}% — long-term engagement needs attention.`);
  1258|  }
  1259|  if (conversionRate > 0) {
  1260|    parts.push(`${conversionRate}% converted to investment — strong performance.`);
  1261|  } else if (size > 10) {
  1262|    parts.push('No conversions yet — focus on moving engaged members to interested stage.');
